<div class="section-head"><h1><?= e($label) ?></h1><?php if(!$readonly): ?><a class="button" href="/admin/<?= e($table) ?>/create">＋ 新增记录</a><?php endif ?></div><form method="get" class="filter-bar"><label>查找记录<input name="q" value="<?= e(Yii::$app->request->get('q','')) ?>"></label><button>搜索</button></form><p class="meta">共 <?= (int)$provider->totalCount ?> 条记录</p><div class="table-scroll"><table><thead><tr><th>ID</th><th>记录摘要</th><th>操作</th></tr></thead><tbody><?php foreach($provider->models as $m): ?><tr><td><?= (int)$m->id ?></td><td class="admin-summary"><?php $i=0; foreach($m->attributes as $key=>$value): ?><?php if(in_array($key,['id','raw_payload_json','created_at','updated_at','body','content_original','content_cn'],true)||$value===null) {continue;} if(++$i>7) {break;} ?><span><b><?= e($m->getAttributeLabel($key)) ?>:</b> <?= e(mb_substr((string)$value,0,140)) ?></span><?php endforeach ?></td><td><?php if(!$readonly): ?><a href="/admin/<?= e($table) ?>/edit?id=<?= (int)$m->id ?>">编辑</a><form method="post" action="/admin/<?= e($table) ?>/delete" data-confirm="确定删除这条记录？"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$m->id ?>"><button class="text-button">删除</button></form><?php else: ?><?php $type=match($table){'forum_threads'=>'thread','forum_replies'=>'reply','forum_reports'=>'report',default=>null}; if($type): ?><form method="post" action="/admin/moderate"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$m->id ?>"><input type="hidden" name="type" value="<?= e($type) ?>"><?php $operations=$type==='report'?['resolve'=>'处理完成','dismiss'=>'驳回']:['hide'=>'隐藏','publish'=>'恢复公开']; if($type==='thread') {$operations+=['lock'=>'锁定','unlock'=>'解锁','pin'=>'置顶','unpin'=>'取消置顶'];} foreach($operations as $key=>$text): ?><button name="operation" value="<?= e($key) ?>"><?= e($text) ?></button><?php endforeach ?></form><?php else: ?><span>板块名称与说明由迁移初始化。</span><?php endif ?><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php if(!$provider->models): ?><div class="empty">暂无记录。</div><?php endif ?><?= yii\widgets\LinkPager::widget(['pagination'=>$provider->pagination]) ?>
